window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4383b868c317a0aa"]={"versions": [{"id": "FIG-4383b868c317a0aa", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Configuration-Metamodells (ECUC Parameter Configuration). Es definiert die Konfigurationsstruktur und Parameterdefinitionen für die Schlafmodi (<code>EcuMSleepMode</code>) im Kontext des ECU State Managers (<code>EcuM</code>) und bindet externe Konfigurationscontainer des Microcontroller Drivers (<code>MCU</code>) ein.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst folgende Container- und Parameterdefinitionen:</p>\n<ul class=\"fig-list\">\n<li><code>EcuMSleepMode</code> (<code>EcucParamConfContainerDef</code>, Multiplizität: <code>1..*</code>): Zentraler Konfigurationscontainer für Schlafeinstellungen des Steuergeräts.</li>\n<li><code>EcuMSleepModeId</code> (<code>EcucIntegerParamDef</code> via Komposition <code>+parameter</code>): Ganzzahliger Bezeichner des Schlafmodus mit Wertebereich <code>min = 0</code>, <code>max = 255</code> und Eigenschaft <code>symbolicNameValue = true</code>.</li>\n<li><code>EcuMSleepModeSuspend</code> (<code>EcucBooleanParamDef</code> via Komposition <code>+parameter</code>): Boolescher Schalter zur Festlegung, ob der Modus ein Suspend-Modus ist.</li>\n<li><code>EcuMSleepModeMcuModeRef</code> (<code>EcucSymbolicNameReferenceDef</code> via Komposition <code>+reference</code>): Symbolische Referenz mit Ziel (<code>+destination</code>) auf den Container <code>McuModeSettingConf</code> (<code>EcucParamConfContainerDef</code>, Multiplizität: <code>1..*</code>, Herkunft: <code>(from MCU)</code>).</li>\n<li><code>EcuMWakeupSourceMask</code> (<code>EcucSymbolicNameReferenceDef</code>, Multiplizität: <code>1..<em></code> via Komposition <code>+reference</code>): Symbolische Referenz mit Ziel (<code>+destination</code>) auf den Container <code>EcuMWakeupSource</code> (<code>EcucParamConfContainerDef</code>, Multiplizität: <code>1..</em></code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein statisches Konfigurationsmetamodell ohne dynamische Ablauf- oder Zustandsübergangssemantik. Zur Laufzeit dient die Konfiguration der Parametrierung des EcuM beim Versetzen des Steuergeräts in definierte Schlaf- bzw. Halt-Zustände sowie der Zuordnung der aufweckberechtigten Quellen und des zu aktivierenden MCU-Modus.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfiguratoren und Generatoren müssen sicherstellen, dass mindestens ein <code>EcuMSleepMode</code> definiert ist. Jeder Modus muss eine eindeutige <code>EcuMSleepModeId</code> im Bereich 0 bis 255 erhalten. Für jeden Schlafmodus muss genau ein zugehöriger MCU-Modus (<code>McuModeSettingConf</code>) referenziert werden sowie mindestens eine Aufweckquelle (<code>EcuMWakeupSourceMask</code>) über die <code>EcuMWakeupSource</code>-Definitionen eingebunden sein.</p>"}, {"id": "FIG-1727f6f8fc10bd9a", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Configuration-Metamodells (ECUC Parameter Configuration). Es definiert die Konfigurationsstruktur und Parameterdefinitionen für die Schlafmodi (<code>EcuMSleepMode</code>) im Kontext des ECU State Managers (<code>EcuM</code>) und bindet externe Konfigurationscontainer des Microcontroller Drivers (<code>MCU</code>) ein.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst folgende Container- und Parameterdefinitionen:</p>\n<ul class=\"fig-list\">\n<li><code>EcuMSleepMode</code> (<code>EcucParamConfContainerDef</code>, Multiplizität: <code>1..*</code>): Zentraler Konfigurationscontainer für Schlafeinstellungen des Steuergeräts.</li>\n<li><code>EcuMSleepModeId</code> (<code>EcucIntegerParamDef</code> via Komposition <code>+parameter</code>): Ganzzahliger Bezeichner des Schlafmodus mit Wertebereich <code>min = 0</code>, <code>max = 255</code> und Eigenschaft <code>symbolicNameValue = true</code>.</li>\n<li><code>EcuMSleepModeSuspend</code> (<code>EcucBooleanParamDef</code> via Komposition <code>+parameter</code>): Boolescher Schalter zur Festlegung, ob der Modus ein Suspend-Modus ist.</li>\n<li><code>EcuMSleepModeMcuModeRef</code> (<code>EcucSymbolicNameReferenceDef</code> via Komposition <code>+reference</code>): Symbolische Referenz mit Ziel (<code>+destination</code>) auf den Container <code>McuModeSettingConf</code> (<code>EcucParamConfContainerDef</code>, Multiplizität: <code>1..*</code>, Herkunft: <code>(from MCU)</code>).</li>\n<li><code>EcuMWakeupSourceMask</code> (<code>EcucSymbolicNameReferenceDef</code>, Multiplizität: <code>1..<em></code> via Komposition <code>+reference</code>): Symbolische Referenz mit Ziel (<code>+destination</code>) auf den Container <code>EcuMWakeupSource</code> (<code>EcucParamConfContainerDef</code>, Multiplizität: <code>1..</em></code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein statisches Konfigurationsmetamodell ohne dynamische Ablauf- oder Zustandsübergangssemantik. Zur Laufzeit dient die Konfiguration der Parametrierung des EcuM beim Versetzen des Steuergeräts in definierte Schlaf- bzw. Halt-Zustände sowie der Zuordnung der aufweckberechtigten Quellen und des zu aktivierenden MCU-Modus.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfiguratoren und Generatoren müssen sicherstellen, dass mindestens ein <code>EcuMSleepMode</code> definiert ist. Jeder Modus muss eine eindeutige <code>EcuMSleepModeId</code> im Bereich 0 bis 255 erhalten. Für jeden Schlafmodus muss genau ein zugehöriger MCU-Modus (<code>McuModeSettingConf</code>) referenziert werden sowie mindestens eine Aufweckquelle (<code>EcuMWakeupSourceMask</code>) über die <code>EcuMWakeupSource</code>-Definitionen eingebunden sein.</p>"}, {"id": "FIG-c66ce12027c2ebf8", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-ECU-Configuration-Metamodells (ECUC Parameter Configuration). Es definiert die Konfigurationsstruktur und Parameterdefinitionen für die Schlafmodi (<code>EcuMSleepMode</code>) im Kontext des ECU State Managers (<code>EcuM</code>) und bindet externe Konfigurationscontainer des Microcontroller Drivers (<code>MCU</code>) ein.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Modell umfasst folgende Container- und Parameterdefinitionen:</p>\n<ul class=\"fig-list\">\n<li><code>EcuMSleepMode</code> (<code>EcucParamConfContainerDef</code>, Multiplizität: <code>1..256</code>): Zentraler Konfigurationscontainer für Schlafeinstellungen des Steuergeräts.</li>\n<li><code>EcuMSleepModeId</code> (<code>EcucIntegerParamDef</code> via Komposition <code>+parameter</code>): Ganzzahliger Bezeichner des Schlafmodus mit Wertebereich <code>min = 0</code>, <code>max = 255</code> und Eigenschaft <code>symbolicNameValue = true</code>.</li>\n<li><code>EcuMSleepModeSuspend</code> (<code>EcucBooleanParamDef</code> via Komposition <code>+parameter</code>): Boolescher Schalter zur Festlegung, ob der Modus ein Suspend-Modus ist.</li>\n<li><code>EcuMSleepModeMcuModeRef</code> (<code>EcucSymbolicNameReferenceDef</code> via Komposition <code>+reference</code>): Symbolische Referenz mit Ziel (<code>+destination</code>) auf den Container <code>McuModeSettingConf</code> (<code>EcucParamConfContainerDef</code>, Multiplizität: <code>1..*</code>, Herkunft: <code>(from MCU)</code>).</li>\n<li><code>EcuMWakeupSourceMask</code> (<code>EcucSymbolicNameReferenceDef</code>, Multiplizität: <code>1..*</code> via Komposition <code>+reference</code>): Symbolische Referenz mit Ziel (<code>+destination</code>) auf den Container <code>EcuMWakeupSource</code> (<code>EcucParamConfContainerDef</code>, Multiplizität: <code>1..32</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt ein statisches Konfigurationsmetamodell ohne dynamische Ablauf- oder Zustandsübergangssemantik. Zur Laufzeit dient die Konfiguration der Parametrierung des EcuM beim Versetzen des Steuergeräts in definierte Schlaf- bzw. Halt-Zustände sowie der Zuordnung der aufweckberechtigten Quellen und des zu aktivierenden MCU-Modus.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konfiguratoren und Validierungswerkzeuge müssen die Obergrenzen einhalten: Es dürfen maximal 256 <code>EcuMSleepMode</code>-Container (Kardinalität <code>1..256</code>) und maximal 32 <code>EcuMWakeupSource</code>-Container (Kardinalität <code>1..32</code>) definiert werden, passend zur bitweisen Abbildung in Masken. Jeder Schlafmodus benötigt eine eindeutige <code>EcuMSleepModeId</code> (0..255), eine Referenz auf <code>McuModeSettingConf</code> und mindestens eine zugewiesene Aufweckquelle (<code>EcuMWakeupSourceMask</code>).</p>"}], "trans": [{"from": "FIG-4383b868c317a0aa", "to": "FIG-1727f6f8fc10bd9a", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1727f6f8fc10bd9a", "to": "FIG-c66ce12027c2ebf8", "fr": "R4.1.3", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>EcuMSleepMode: Multiplizität von <code>1..<em></code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = </em></code>) auf <code>1..256</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 256</code>) eingeschränkt.</li>\n<li>EcuMWakeupSource: Multiplizität von <code>1..<em></code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = </em></code>) auf <code>1..32</code> (<code>lowerMultiplicity = 1</code>, <code>upperMultiplicity = 32</code>) eingeschränkt.</li>\n</ul>"}]};
